export const BattleCombatState_1 = Schema.Struct({ "can_escape": Schema.Boolean.annotate({ "description": "Whether your ship can make escape progress. False when the ship is warp-disrupted (warp_disrupted), intercepted by a latched-on boarder that out-runs it (intercepted), or has no fit crew to operate it (incapacitated). Those three are independent and can hold together, so read each boolean rather than inferring a single cause from this field. True still requires flee stance and the required escape ticks." }), "disruption_ticks": Schema.optionalKey(Schema.Number.annotate({ "description": "Remaining ticks of EM disruption (present only while em_disrupted)." }).check(Schema.isInt().annotate({ "expected": "an integer" }))), "effective_speed": Schema.Number.annotate({ "description": "Your derived combat speed after fitted modules, temporary buffs, pilot skills, EM disruption, and enemy webifiers. This value drives hit chance, maneuvering, escape, and boarding pursuit." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "em_disrupted": Schema.Boolean.annotate({ "description": "An EM-damage disruption debuff is active on you (reduces speed and damage output for a few ticks)." }), "flee_counter": Schema.Number.annotate({ "description": "Consecutive flee ticks accumulated. Counts only while in the flee stance at the outer ring; resets if you stop fleeing." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "flee_required": Schema.optionalKey(Schema.Number.annotate({ "description": "Flee ticks needed to escape under current conditions. 3 ticks is the baseline, and the combat-speed gap to the fastest enemy ship moves it either way: being slower (or webbed) raises it, being faster lowers it, with a floor of 1. Omitted while escape progress is blocked — by warp disruption or by a boarding intercept alike — so its absence does not identify which. Read warp_disrupted and intercepted for that." }).check(Schema.isInt().annotate({ "expected": "an integer" }))), "incapacitated": Schema.Boolean.annotate({ "description": "Always present in the requesting participant's combat_state. True means no fit crew can operate your ship; false means personnel can operate it. Independent of warp_disrupted: both may be true. When true can_escape is false and the ship cannot fire or move. Not included for observers or other participants. Injured crew may recover automatically while the ship remains intact and uncaptured; ship status reports the recovery timing." }), "intercepted": Schema.Boolean.annotate({ "description": "A boarding pursuer that has latched on and out-runs your ship is cancelling your retreat and flee movement. Independent of warp_disrupted and incapacitated: any combination of the three can be true at once, and each blocks escape on its own. Match or beat its effective speed, or destroy it, to resume escape progress. interceptor_id names the pursuer." }), "intercepting": Schema.Boolean.annotate({ "description": "Your own boarding attempt is out-running its target, cancelling that target's retreat and flee movement. This is the boarder's side of intercepted; combat_state is self-only and get_battle_status does not publish another ship's stance or speed, so this is the only way to confirm your pursuit is holding. intercepting_target_id names the ship." }), "intercepting_target_id": Schema.optionalKey(Schema.String.annotate({ "description": "player_id of the ship your boarding attempt is out-running, matching a participant row in the same get_battle_status response. Present exactly when intercepting is true." })), "interceptor_id": Schema.optionalKey(Schema.String.annotate({ "description": "player_id of the boarder intercepting you, matching a participant row in the same get_battle_status response. Present exactly when intercepted is true. At most one hull can intercept you: a ship already in a boarding link cannot open a second one." })), "latch_status": Schema.optionalKey(Schema.Literals(["accruing", "shields_holding", "out_of_range"]).annotate({ "description": "Whether your own boarding latch is gaining ground, and what is stopping it when it is not. accruing: you hold point-blank contact with the target's shields suppressed, so latch progress accrues this tick. shields_holding: the target's shields have regenerated back above the suppression line, so the latch reverts instead of advancing — keep its shields down to reopen the gate. out_of_range: you are not in point-blank contact, so the latch reverts — close the gap first, because suppressing shields does nothing at range. Present only while you are latching onto a target; omitted once marines are aboard, and omitted for the ship being boarded." })), "max_weapon_reach": Schema.Number.annotate({ "description": "Largest zone distance any fitted weapon can fire against your selected target after its targeting-range reductions. A target whose zone_distance exceeds this is out of range." }).check(Schema.isInt().annotate({ "expected": "an integer" })), "speed_penalty_pct": Schema.optionalKey(Schema.Number.annotate({ "description": "Current speed reduction from EM disruption as a percentage (present only while em_disrupted)." }).check(Schema.isInt().annotate({ "expected": "an integer" }))), "warp_disrupted": Schema.Boolean.annotate({ "description": "An enemy warp disruptor/scrambler is blocking your escape (net of your own warp core stabilizers). Kill the tackler or out-stabilize it to break free." }), "web_strength_pct": Schema.optionalKey(Schema.Number.annotate({ "description": "Combined combat-speed penalty from enemy webifiers as a percentage. Webifier penalties add and cap at 75%." }).check(Schema.isInt().annotate({ "expected": "an integer" }))), "webbed": Schema.Boolean.annotate({ "description": "An enemy stasis webifier is reducing your effective combat speed." }) }).annotate({ "identifier": "BattleCombatState_1" });
